"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[480],{5480:(e,n,t)=>{t.r(n),t.d(n,{default:()=>i});let i={id:"en",viName:"tiếng Anh",nameEn:"English",nameNative:"English",flag:"\uD83C\uDDEC\uD83C\uDDE7",appTitle:"Teacher AI — Học tiếng Anh c\xf9ng AI",appDescription:"Luyện giao tiếp tiếng Anh theo ng\xe0nh nghề c\xf9ng gia sư AI, d\xe0nh cho người Việt.",shortName:"Teacher AI",speechLang:"en-US",langPrefix:"en",levelSystem:"CEFR",levelLabels:{A1:"A1",A2:"A2",B1:"B1",B2:"B2"},phoneticName:"",scriptMode:"latin",targetScript:/[A-Za-z]{2,}/,targetRun:/[A-Za-z][A-Za-z0-9'’\-\s,.;:!?]*/g,sentenceEnd:".!?",minDialogueChars:6,minBoldWords:3,recognitionHint:"N\xf3i bằng tiếng Anh",welcome:{headline:"Xin ch\xe0o! C\xf9ng n\xf3i tiếng Anh tự tin hơn nh\xe9.",greeting:"Hello! Let's practice English together today."},pronunciationFocus:"missing final consonant sounds such as /s/, /z/, /t/, /d/, /k/, /ʃ/, /tʃ/, /θ/, incorrect word stress, and consonant clusters",promptNotes:'Teaching language: English. Level system: CEFR (A1–B2).\n- Put every English sentence the learner should say inside double quotes "...".',pedagogy:{A1:"- Explain mostly in Vietnamese (about 70%); English only in short model sentences of 3–7 words.\n- One new item per turn. Always give the Vietnamese meaning next to a new English sentence.\n- Tasks: repeat after me, choose A or B, complete one word. Accept one-word answers, then model the full sentence.\n- Correct only the most important mistake each turn; be very encouraging.",A2:'- Mix Vietnamese explanations (about 50%) with simple English. Model sentences up to 10 words.\n- Focus on everyday phrases, present/past simple, questions. Give a hint like (Gợi \xfd: "I usually…") for each task.\n- Tasks: short answers in full sentences, simple role-plays with 2–3 exchanges.\n- Correct up to two mistakes per turn, mainly grammar and word choice.',B1:'- Teach mostly in English (about 70%), Vietnamese only for tricky grammar or meaning.\n- Role-plays with longer exchanges; ask follow-up "why/how" questions to make the learner explain.\n- Introduce linkers and natural collocations; push for 2–3 sentence answers.\n- Correct all errors that affect meaning, plus Vietlish word order; offer a more natural alternative.',B2:"- Teach in English; use Vietnamese only if the learner asks.\n- Discussions, negotiations and problem-solving situations; challenge the learner's opinions.\n- Focus on precision, register (formal/informal), idioms and complex structures.\n- Correct accuracy and naturalness, including better word choices and more sophisticated phrasing."},accents:[{id:"us",group:"Bắc Mỹ",flag:"\uD83C\uDDFA\uD83C\uDDF8",name:"Mỹ – chuẩn",locales:["en-US"],prompt:"a neutral General American",sample:"Hi there! Let's practise ordering coffee. Could I get a medium latte, please?"},{id:"us-south",group:"Bắc Mỹ",flag:"\uD83C\uDDFA\uD83C\uDDF8",name:"Mỹ – miền Nam (Texas)",locales:["en-US"],prompt:"a warm Southern United States (Texas)",sample:"Well, howdy! It's mighty nice to meet y'all. How's your day going?"},{id:"us-ny",group:"Bắc Mỹ",flag:"\uD83C\uDDFA\uD83C\uDDF8",name:"Mỹ – New York",locales:["en-US"],prompt:"a New York City",sample:"Hey, how you doing? The subway's right around the corner, you can't miss it."},{id:"ca",group:"Bắc Mỹ",flag:"\uD83C\uDDE8\uD83C\uDDE6",name:"Canada",locales:["en-CA"],prompt:"a Canadian English",sample:"Hey, it's pretty cold out today, eh? Let's grab a coffee and warm up."},{id:"uk",group:"Anh & Ireland",flag:"\uD83C\uDDEC\uD83C\uDDE7",name:"Anh – chuẩn (RP)",locales:["en-GB"],prompt:"a standard British Received Pronunciation",sample:"Good afternoon. Would you like a cup of tea before we begin the lesson?"},{id:"uk-london",group:"Anh & Ireland",flag:"\uD83C\uDDEC\uD83C\uDDE7",name:"Anh – London",locales:["en-GB"],prompt:"a modern London (Estuary English)",sample:"Alright mate? The bus to Camden is just over there, about five minutes."},{id:"uk-north",group:"Anh & Ireland",flag:"\uD83C\uDDEC\uD83C\uDDE7",name:"Anh – miền Bắc (Manchester)",locales:["en-GB"],prompt:"a Northern English (Manchester)",sample:"Ey up! It's a lovely day, int it? Fancy a brew before the match?"},{id:"scot",group:"Anh & Ireland",flag:"\uD83C\uDFF4",name:"Scotland",locales:["en-GB-scotland","en-GB"],prompt:"a Scottish (Edinburgh)",sample:"Hello there! Welcome to Edinburgh. The castle is just up the hill."},{id:"ie",group:"Anh & Ireland",flag:"\uD83C\uDDEE\uD83C\uDDEA",name:"Ireland",locales:["en-IE"],prompt:"an Irish (Dublin)",sample:"How's it going? Grand weather today, so let's go for a walk by the river."},{id:"au",group:"\xdac & New Zealand",flag:"\uD83C\uDDE6\uD83C\uDDFA",name:"\xdac",locales:["en-AU"],prompt:"an Australian",sample:"G'day! How are you going? Let's head down to the beach this arvo."},{id:"nz",group:"\xdac & New Zealand",flag:"\uD83C\uDDF3\uD83C\uDDFF",name:"New Zealand",locales:["en-NZ"],prompt:"a New Zealand",sample:"Kia ora! Sweet as, I'll meet you at the caf\xe9 at ten."},{id:"in",group:"Ch\xe2u \xc1 & ch\xe2u Phi",flag:"\uD83C\uDDEE\uD83C\uDDF3",name:"Ấn Độ",locales:["en-IN"],prompt:"an Indian English",sample:"Good morning! Kindly share the report by today evening, it will be very helpful."},{id:"sg",group:"Ch\xe2u \xc1 & ch\xe2u Phi",flag:"\uD83C\uDDF8\uD83C\uDDEC",name:"Singapore",locales:["en-SG"],prompt:"a Singaporean English",sample:"Hello! The meeting is at three, can? Please bring the documents."},{id:"ph",group:"Ch\xe2u \xc1 & ch\xe2u Phi",flag:"\uD83C\uDDF5\uD83C\uDDED",name:"Philippines",locales:["en-PH"],prompt:"a Filipino English",sample:"Hi po! Thank you for calling. How may I help you today?"},{id:"za",group:"Ch\xe2u \xc1 & ch\xe2u Phi",flag:"\uD83C\uDDFF\uD83C\uDDE6",name:"Nam Phi",locales:["en-ZA"],prompt:"a South African",sample:"Howzit! The meeting has been moved to tomorrow morning at nine."},{id:"ng",group:"Ch\xe2u \xc1 & ch\xe2u Phi",flag:"\uD83C\uDDF3\uD83C\uDDEC",name:"Nigeria",locales:["en-NG"],prompt:"a Nigerian English",sample:"Good afternoon! You are welcome. Please, how can I assist you?"}],profiles:[{id:"business",title:"Tiếng Anh c\xf4ng sở",subtitle:"Họp h\xe0nh, email v\xe0 đ\xe0m ph\xe1n",icon:"business",color:"blue",scene:"Trao đổi trong cuộc họp",prompt:'Ch\xe0o bạn! C\xf4 l\xe0 Maya, gia sư tiếng Anh của bạn. H\xf4m nay ch\xfang ta sẽ luyện tập tiếng Anh c\xf4ng sở trong t\xecnh huống: "Trao đổi trong cuộc họp". C\xf4 sẽ l\xe0 đồng nghiệp của bạn nh\xe9. Đầu ti\xean, h\xe3y ho\xe0n th\xe0nh c\xe2u ch\xe0o n\xe0y: "Good morning, everyone. Our team is working on..." (H\xe3y điền tiếp c\xf4ng việc của nh\xf3m bạn nh\xe9!)',words:["Could you clarify that?","Let's get started.","I see your point."]},{id:"travel",title:"Tiếng Anh du lịch",subtitle:"Tự tin giao tiếp khi đi du lịch",icon:"travel",color:"orange",scene:"L\xe0m thủ tục nhận ph\xf2ng",prompt:'Ch\xe0o bạn! C\xf4 l\xe0 Maya. H\xf4m nay ch\xfang ta c\xf9ng luyện tiếng Anh du lịch trong t\xecnh huống: "L\xe0m thủ tục nhận ph\xf2ng kh\xe1ch sạn". C\xf4 l\xe0 nh\xe2n vi\xean lễ t\xe2n nh\xe9: "Welcome to Grand Hotel! Do you have a reservation under your name?" Bạn h\xe3y thử trả lời c\xe2u hỏi n\xe0y nh\xe9 (V\xed dụ: "Yes, I have a reservation under the name Nam.").',words:["I'd like to check in.","Is breakfast included?","Could I have a receipt?"]},{id:"technology",title:"Tiếng Anh ng\xe0nh c\xf4ng nghệ",subtitle:"L\xe0m việc nh\xf3m, thuyết tr\xecnh v\xe0 phỏng vấn",icon:"technology",color:"purple",scene:"Phỏng vấn vị tr\xed lập tr\xecnh vi\xean",prompt:'Ch\xe0o bạn! C\xf4 l\xe0 Maya. H\xf4m nay ch\xfang ta sẽ luyện phỏng vấn tiếng Anh ng\xe0nh c\xf4ng nghệ (IT). C\xf4 l\xe0 người phỏng vấn bạn nh\xe9: "Welcome! Could you briefly introduce yourself and the main technologies you use?" (H\xe3y giới thiệu ngắn về bản th\xe2n v\xe0 c\xf4ng nghệ bạn d\xf9ng nh\xe9!).',words:["I narrowed down the cause.","The issue was resolved.","It scales well."]},{id:"healthcare",title:"Tiếng Anh chuy\xean ng\xe0nh y khoa",subtitle:"Giao tiếp l\xe2m s\xe0ng v\xe0 chăm s\xf3c bệnh nh\xe2n",icon:"healthcare",color:"green",scene:"Hỏi thăm bệnh nh\xe2n",prompt:'Ch\xe0o bạn! C\xf4 l\xe0 Maya. H\xf4m nay ch\xfang ta c\xf9ng thực h\xe0nh giao tiếp tiếng Anh y tế trong t\xecnh huống: "Hỏi thăm triệu chứng bệnh nh\xe2n". Bạn l\xe0 b\xe1c sĩ/y t\xe1, h\xe3y bắt đầu bằng c\xe2u: "Good morning, what brings you in today?" (Ch\xe0o buổi s\xe1ng, điều g\xec khiến bạn đến kh\xe1m h\xf4m nay?). Bạn h\xe3y thử n\xf3i c\xe2u n\xe0y nh\xe9!',words:["Where does it hurt?","How long have you felt this way?","Take a deep breath."]},{id:"finance",title:"Tiếng Anh ng\xe0nh t\xe0i ch\xednh",subtitle:"B\xe1o c\xe1o, kh\xe1ch h\xe0ng v\xe0 ng\xe2n h\xe0ng",icon:"finance",color:"pink",scene:"Tr\xecnh b\xe0y b\xe1o c\xe1o th\xe1ng",prompt:"Let’s practice presenting a financial report in English. Begin with: “Revenue increased by...” What changed in your figures this month?",words:["Revenue increased by…","Compared with last month…","The main driver was…"]},{id:"everyday",title:"Tiếng Anh giao tiếp hằng ng\xe0y",subtitle:"Tr\xf2 chuyện tự nhi\xean v\xe0 tự tin",icon:"everyday",color:"yellow",scene:"L\xe0m quen với người mới",prompt:"Hi! It’s nice to meet you. What do you like to do in your free time? You can begin: “I like...”",words:["That sounds interesting.","How about you?","I haven't tried that yet."]},{id:"refrigeration",title:"Tiếng Anh kỹ thuật lạnh",subtitle:"Thiết bị lạnh, bảo tr\xec v\xe0 an to\xe0n",icon:"refrigeration",color:"blue",scene:"B\xe0n giao thiết bị lạnh",prompt:"Hello! I’m a customer reporting an issue with a refrigeration unit. Ask me about the equipment, the symptoms, and when the problem started. Use clear technical English.",words:["The unit is not cooling properly.","Please switch off the power.","Could you describe the noise?"]}],phraseMeanings:{"Could you clarify that?":"Bạn c\xf3 thể giải th\xedch r\xf5 hơn kh\xf4ng?","Let's get started.":"Ch\xfang ta bắt đầu nh\xe9.","I see your point.":"T\xf4i hiểu \xfd của bạn.","I'd like to check in.":"T\xf4i muốn l\xe0m thủ tục nhận ph\xf2ng.","Is breakfast included?":"Gi\xe1 ph\xf2ng đ\xe3 bao gồm bữa s\xe1ng chưa?","Could I have a receipt?":"Cho t\xf4i xin h\xf3a đơn được kh\xf4ng?","I narrowed down the cause.":"T\xf4i đ\xe3 khoanh v\xf9ng được nguy\xean nh\xe2n.","The issue was resolved.":"Sự cố đ\xe3 được khắc phục.","It scales well.":"Hệ thống c\xf3 thể mở rộng tốt.","Where does it hurt?":"Bạn đau ở đ\xe2u?","How long have you felt this way?":"Bạn cảm thấy như vậy bao l\xe2u rồi?","Take a deep breath.":"H\xe3y h\xedt một hơi thật s\xe2u.","Revenue increased by…":"Doanh thu tăng ...","Compared with last month…":"So với th\xe1ng trước...","The main driver was…":"Nguy\xean nh\xe2n ch\xednh l\xe0...","That sounds interesting.":"Nghe th\xfa vị đấy.","How about you?":"C\xf2n bạn th\xec sao?","I haven't tried that yet.":"T\xf4i vẫn chưa thử điều đ\xf3.","The unit is not cooling properly.":"Thiết bị kh\xf4ng l\xe0m lạnh đ\xfang c\xe1ch.","Please switch off the power.":"Vui l\xf2ng ngắt nguồn điện.","Could you describe the noise?":"Bạn c\xf3 thể m\xf4 tả tiếng ồn kh\xf4ng?"},suggestions:{business:["Our team is working on the new quarterly budget.","Could you please explain that in simpler terms?","C\xf4 giải th\xedch lại bằng tiếng Việt gi\xfap em với.","Yes, I agree with your proposal."],travel:["Yes, I have a reservation under the name Nam.","Could you recommend a good local restaurant nearby?","Nhờ c\xf4 hướng dẫn em c\xe1ch ph\xe1t \xe2m c\xe2u vừa rồi.","What time is checkout tomorrow morning?"],technology:["I solved an issue with API latency by adding caching.","Could you give me an example answer for this question?","C\xf4 chỉ ra lỗi ngữ ph\xe1p gi\xfap em nh\xe9.","We use microservices and Docker containers."],healthcare:["Good morning. Where does it hurt the most?","How long have you been experiencing these symptoms?","C\xf4 đọc lại c\xe2u mẫu bằng tiếng Anh gi\xfap em nh\xe9.","Please take a deep breath and relax."],finance:["I would like to open a business savings account.","Could you clarify the annual interest rate?","C\xf4 cho em một v\xed dụ thực tế trong ng\xe2n h\xe0ng nh\xe9.","What documents do I need to prepare?"],refrigeration:["The refrigerant pressure is too low, we should check for leaks.","Could you repeat the technical term in English?","C\xf4 giải th\xedch từ chuy\xean ng\xe0nh n\xe0y gi\xfap em.","The compressor temperature seems normal now."],everyday:["Hi Maya! I had a very busy and productive day.","What is the most natural way to say this in English?","C\xf4 dạy em mẫu c\xe2u giao tiếp tiếp theo nh\xe9.","Nice to meet you! How are you doing today?"]},placement:[{question:"Choose the grammatically correct sentence.",options:["She go to work every day.","She goes to work every day.","She going to work every day."],answer:1,explanation:"With he, she, or it in the present simple, most verbs take -s or -es."},{question:"Complete the sentence: “There ___ two appointments this afternoon.”",options:["is","are","be"],answer:1,explanation:"Use are with a plural noun in there is/are sentences."},{question:"Choose the correct negative sentence.",options:["We didn't received the email.","We don't received the email.","We didn't receive the email."],answer:2,explanation:"Use did not + the base form of the verb in the past simple."},{question:"Choose the best response: “Could you give me a hand?”",options:["“Of course. What do you need?”","“I have two hands.”","“It is in my wallet.”"],answer:0,explanation:"“Give me a hand” is an informal request for help."},{question:"Complete the sentence: “I ___ this equipment before.”",options:["have used","used yesterday","am using"],answer:0,explanation:"Use the present perfect to describe experience without naming a finished time."},{question:"Choose the sentence with the correct modal verb.",options:["You must to wear safety glasses.","You must wear safety glasses.","You must wearing safety glasses."],answer:1,explanation:"A modal verb such as must is followed by the base form without to."},{question:"Complete the sentence: “If I ___ more time, I would review the report.”",options:["have","will have","had"],answer:2,explanation:"The second conditional uses if + past simple, followed by would + base verb."},{question:"Complete the formal recommendation: “The device ___ inspected before use.”",options:["should be","should to be","should being"],answer:0,explanation:"Use modal + be + past participle to form a passive recommendation."}],tutors:{maya:{name:"Ms. Maya",title:"Gia sư Nữ Tận T\xe2m",tagline:"Dịu d\xe0ng, ph\xe1t \xe2m chuẩn, ki\xean nhẫn hướng dẫn",description:"C\xf4 gi\xe1o nhiệt t\xecnh, hướng dẫn tỉ mỉ từng ph\xe1t \xe2m v\xe0 ngữ ph\xe1p theo tr\xecnh độ học vi\xean.",greeting:"H\xf4m nay c\xf4 sẽ đồng h\xe0nh c\xf9ng em luyện n\xf3i tiếng Anh thật tự tin nh\xe9."},david:{name:"Mr. David",title:"Gia sư Nam Bản Xứ",tagline:"Phong th\xe1i đĩnh đạc, ngữ điệu Anh-Mỹ tự nhi\xean",description:"Thầy gi\xe1o phong c\xe1ch phương T\xe2y, phản xạ nhanh v\xe0 chuy\xean s\xe2u giao tiếp c\xf4ng việc.",greeting:"Ready to practice speaking naturally today?"},alex:{name:"Nova",title:"Linh Vật Học Tập",tagline:"Đ\xe1ng y\xeau, hoạt b\xe1t, học tập kh\xf4ng \xe1p lực",description:"Bạn nhỏ tr\xf2n xinh, hồn nhi\xean v\xe0 vui t\xednh, mầm l\xe1 tr\xean đầu lớn l\xean c\xf9ng mỗi b\xe0i học của bạn.",greeting:"Hi hi! C\xf9ng nhau học tiếng Anh thật vui n\xe0o!"}},grammarTopics:[{id:"be-present",level:"A1",title:"Động từ To Be ở hiện tại đơn (am / is / are)",structure:"Chủ ngữ (Subject) + am / is / are",overview:"Động từ 'to be' d\xf9ng để giới thiệu t\xean, nghề nghiệp, cảm x\xfac, vị tr\xed v\xe0 t\xednh chất. Người Việt hay mắc lỗi bỏ qu\xean 'to be' (v\xed dụ n\xf3i 'I tired' thay v\xec 'I am tired'). Quy tắc: I đi với am; He/She/It v\xe0 danh từ số \xedt đi với is; You/We/They v\xe0 danh từ số nhiều đi với are.",examples:["I am ready for the lesson. (T\xf4i đ\xe3 sẵn s\xe0ng cho buổi học.)","The machines are in the workshop. (C\xe1c m\xe1y m\xf3c đang ở trong xưởng.)"],questions:[{prompt:"Choose the correct sentence.",options:["They is ready.","They are ready.","They be ready."],answer:1,explanation:"Chủ ngữ 'They' (họ/ch\xfang n\xf3) l\xe0 số nhiều, bắt buộc d\xf9ng 'are'."},{prompt:"Complete: “I ___ a technician.”",options:["am","is","are"],answer:0,explanation:"Đại từ 'I' (t\xf4i) lu\xf4n đi với động từ to be 'am'."},{prompt:"Choose the correct question.",options:["Is you tired?","Are you tired?","Do you be tired?"],answer:1,explanation:"Với c\xe2u hỏi c\xf3 to be, đảo am/is/are l\xean trước chủ ngữ. 'You' đi với 'Are you tired?'."}]},{id:"present-simple",level:"A1",title:"Th\xec Hiện tại đơn: Th\xf3i quen & Sự thật (Present Simple)",structure:"S + V(nguy\xean thể / th\xeam -s, -es với He, She, It)",overview:"D\xf9ng để diễn tả th\xf3i quen, lịch tr\xecnh v\xe0 sự thật hiển nhi\xean. Lưu \xfd đặc biệt cho người Việt: Tiếng Việt kh\xf4ng chia động từ, nhưng tiếng Anh với ng\xf4i thứ ba số \xedt (He, She, It, danh từ số \xedt), động từ bắt buộc phải th\xeam đu\xf4i -s hoặc -es. Khi phủ định hoặc nghi vấn, mượn trợ động từ do/does.",examples:["We check the temperature every morning. (Ch\xfang t\xf4i kiểm tra nhiệt độ mỗi s\xe1ng.)","She works at the clinic. (C\xf4 ấy l\xe0m việc tại ph\xf2ng kh\xe1m.)"],questions:[{prompt:"Complete: “Mai ___ the bus to work.”",options:["take","takes","taking"],answer:1,explanation:"'Mai' l\xe0 danh từ số \xedt (ng\xf4i She), n\xean động từ 'take' phải th\xeam đu\xf4i -s th\xe0nh 'takes'."},{prompt:"Choose the correct negative sentence.",options:["He doesn't work on Sundays.","He don't works on Sundays.","He not work on Sundays."],answer:0,explanation:"Với ng\xf4i 'He', c\xe2u phủ định d\xf9ng 'doesn't + động từ nguy\xean mẫu' (doesn't work)."},{prompt:"Complete: “___ they start at nine?”",options:["Does","Do","Are"],answer:1,explanation:"Chủ ngữ 'they' ở th\xec hiện tại đơn mượn trợ động từ 'Do' để lập c\xe2u hỏi."}]},{id:"articles",level:"A1",title:"Mạo từ a, an, the (Articles)",structure:"a/an + danh từ đếm được số \xedt; the + danh từ x\xe1c định",overview:"Người Việt thường gặp kh\xf3 khăn v\xec tiếng Việt kh\xf4ng c\xf3 mạo từ tương đương. 'A/An' d\xf9ng cho danh từ số \xedt được nhắc đến lần đầu (d\xf9ng 'an' trước từ ph\xe1t \xe2m bằng nguy\xean \xe2m: a, e, i, o, u). 'The' d\xf9ng khi cả người n\xf3i v\xe0 người nghe đều biết r\xf5 đối tượng đang nhắc tới.",examples:["He is an engineer. (Anh ấy l\xe0 một kỹ sư.)","Please close the door. (L\xe0m ơn h\xe3y đ\xf3ng cửa lại - cửa ph\xf2ng đang ngồi.)"],questions:[{prompt:"Complete: “She is ___ engineer.”",options:["a","an","the"],answer:1,explanation:"Từ 'engineer' bắt đầu bằng nguy\xean \xe2m /e/, n\xean d\xf9ng mạo từ 'an'."},{prompt:"Choose the correct sentence.",options:["I need a information.","I need an information.","I need some information."],answer:2,explanation:"'Information' l\xe0 danh từ kh\xf4ng đếm được, kh\xf4ng d\xf9ng trực tiếp với 'a/an', m\xe0 d\xf9ng 'some'."},{prompt:"Complete: “Please close ___ door; it is making a noise.”",options:["a","an","the"],answer:2,explanation:"D\xf9ng 'the' v\xec c\xe1nh cửa cụ thể m\xe0 cả hai người đều nghe thấy tiếng ồn ph\xe1t ra."}]},{id:"possessives",level:"A1",title:"T\xednh từ sở hữu (Possessive Adjectives)",structure:"my / your / his / her / its / our / their + danh từ",overview:"T\xednh từ sở hữu lu\xf4n đứng trước một danh từ để chỉ quyền sở hữu. Ph\xe2n biệt: His (của anh ấy - nam), Her (của c\xf4 ấy - nữ), Our (của ch\xfang t\xf4i), Their (của họ). Cần lưu \xfd: 'Its' l\xe0 sở hữu của n\xf3; c\xf2n 'It's' l\xe0 viết tắt của 'It is'.",examples:["Our office is near the station. (Văn ph\xf2ng của ch\xfang t\xf4i gần nh\xe0 ga.)","The device has a label on its side. (Thiết bị c\xf3 một nh\xe3n d\xe1n ở b\xean h\xf4ng của n\xf3.)"],questions:[{prompt:"Complete: “Mr. Lee is a doctor. ___ office is on the second floor.”",options:["His","Her","Their"],answer:0,explanation:"'Mr. Lee' l\xe0 nam giới n\xean t\xednh từ sở hữu tương ứng l\xe0 'His' (của anh ấy)."},{prompt:"Choose the correct sentence.",options:["We company is in Hanoi.","Our company is in Hanoi.","Ours company is in Hanoi."],answer:1,explanation:"Đứng trước danh từ 'company' phải d\xf9ng t\xednh từ sở hữu 'Our' (c\xf4ng ty của ch\xfang t\xf4i)."},{prompt:"Complete: “The machine is old, but ___ motor still works.”",options:["its","it's","their"],answer:0,explanation:"'Its' l\xe0 t\xednh từ sở hữu mang nghĩa 'của n\xf3' (cỗ m\xe1y). 'It's' l\xe0 viết tắt của 'It is'."}]},{id:"present-continuous",level:"A2",title:"Th\xec Hiện tại tiếp diễn (Present Continuous)",structure:"S + am / is / are + V-ing",overview:"D\xf9ng để diễn tả h\xe0nh động đang diễn ra ngay l\xfac n\xf3i (right now, at the moment). Người Việt hay qu\xean động từ 'to be' trước 'V-ing' (v\xed dụ n\xf3i 'I waiting' thay v\xec 'I am waiting').",examples:["The nurse is speaking to a patient. (Y t\xe1 đang n\xf3i chuyện với một bệnh nh\xe2n.)","They are not working today. (H\xf4m nay họ kh\xf4ng l\xe0m việc.)"],questions:[{prompt:"Complete: “The team ___ the new system right now.”",options:["tests","is testing","tested"],answer:1,explanation:"C\xf3 trạng từ 'right now' (ngay b\xe2y giờ), chủ ngữ số \xedt 'The team' đi với 'is testing'."},{prompt:"Choose the correct sentence.",options:["I am waiting for the report.","I waiting for the report.","I am wait for the report."],answer:0,explanation:"Hiện tại tiếp diễn bắt buộc phải c\xf3 đầy đủ cấu tr\xfac: to be + V-ing ('am waiting')."},{prompt:"Complete: “What ___ you ___?”",options:["do / do","are / doing","are / do"],answer:1,explanation:"C\xe2u hỏi th\xec tiếp diễn đảo to be l\xean trước: 'What are you doing?' (Bạn đang l\xe0m g\xec thế?)."}]},{id:"comparatives",level:"A2",title:"So s\xe1nh hơn của T\xednh từ (Comparatives)",structure:"T\xednh từ ngắn + -er + than / more + t\xednh từ d\xe0i + than",overview:"D\xf9ng để so s\xe1nh giữa hai người hoặc hai sự vật. T\xednh từ ngắn (1 \xe2m tiết) th\xeam đu\xf4i -er (quiet -> quieter, safe -> safer). T\xednh từ d\xe0i (từ 2 \xe2m tiết trở l\xean) th\xeam 'more' ph\xeda trước. D\xf9ng 'less' nếu muốn diễn đạt mức độ k\xe9m hơn.",examples:["This unit is quieter than the old model. (M\xe1y n\xe0y chạy \xeam hơn m\xe1y cũ.)","The new route is more convenient than the first one. (Tuyến đường mới tiện lợi hơn tuyến đường cũ.)"],questions:[{prompt:"Complete: “This model is ___ than the old one.”",options:["quiet","quieter","the quietest"],answer:1,explanation:"C\xf3 từ 'than' ở ph\xeda sau, cần dạng so s\xe1nh hơn: 'quieter than'."},{prompt:"Choose the correct sentence.",options:["The second route is more safe than the first.","The second route is safer than the first.","The second route is safest than the first."],answer:1,explanation:"'Safe' l\xe0 t\xednh từ ngắn, dạng so s\xe1nh hơn l\xe0 'safer' (kh\xf4ng d\xf9ng 'more safe')."},{prompt:"Complete: “The new process is ___ complicated than before.”",options:["less","least","few"],answer:0,explanation:"D\xf9ng 'less + t\xednh từ d\xe0i + than' để so s\xe1nh k\xe9m hơn (\xedt phức tạp hơn)."}]},{id:"going-to",level:"A2",title:"Dự định tương lai với Be going to",structure:"S + am / is / are + going to + V(nguy\xean thể)",overview:"D\xf9ng để n\xf3i về kế hoạch, dự định đ\xe3 c\xf3 từ trước khi n\xf3i, hoặc dự đo\xe1n điều sắp xảy ra dựa tr\xean dấu hiệu r\xf5 r\xe0ng ở hiện tại. Sau 'going to' lu\xf4n l\xe0 động từ nguy\xean thể kh\xf4ng chia.",examples:["We are going to inspect the equipment tomorrow. (Ch\xfang t\xf4i dự định kiểm tra thiết bị v\xe0o ng\xe0y mai.)","Look at those clouds; it is going to rain. (Nh\xecn những đ\xe1m m\xe2y đen k\xeca, trời sắp mưa rồi.)"],questions:[{prompt:"Complete: “We ___ going to inspect the unit tomorrow.”",options:["is","are","be"],answer:1,explanation:"Chủ ngữ 'We' đi với động từ to be 'are'."},{prompt:"Choose the correct question.",options:["Are you going to call the supplier?","Do you going to call the supplier?","Are you go to call the supplier?"],answer:0,explanation:"C\xe2u hỏi đảo to be: 'Are you going to + V' (Bạn c\xf3 dự định gọi cho nh\xe0 cung cấp kh\xf4ng?)."},{prompt:"Complete: “She isn't going to ___ the meeting.”",options:["attends","attend","attending"],answer:1,explanation:"Sau 'going to' động từ lu\xf4n giữ nguy\xean thể: 'attend'."}]},{id:"past-simple",level:"A2",title:"Th\xec Qu\xe1 khứ đơn (Past Simple)",structure:"S + V-ed / V2 (Bất quy tắc); Phủ định/Nghi vấn: did / didn't + V nguy\xean thể",overview:"D\xf9ng để diễn tả một h\xe0nh động đ\xe3 xảy ra v\xe0 kết th\xfac ho\xe0n to\xe0n trong qu\xe1 khứ tại một thời điểm x\xe1c định (yesterday, last week, ago). Điểm lưu \xfd cốt l\xf5i: Khi đ\xe3 mượn 'did' hoặc 'didn't', động từ ch\xednh ph\xeda sau BẮT BUỘC trở về dạng nguy\xean thể (kh\xf4ng giữ đu\xf4i -ed).",examples:["The technician replaced the filter yesterday. (Kỹ thuật vi\xean đ\xe3 thay tấm lọc ng\xe0y h\xf4m qua.)","Did you receive the report? (Bạn đ\xe3 nhận được bản b\xe1o c\xe1o chưa?)"],questions:[{prompt:"Complete: “We ___ the client yesterday.”",options:["meet","met","have met"],answer:1,explanation:"C\xf3 trạng từ qu\xe1 khứ 'yesterday', d\xf9ng dạng qu\xe1 khứ bất quy tắc của 'meet' l\xe0 'met'."},{prompt:"Choose the correct negative sentence.",options:["She didn't called me.","She didn't call me.","She doesn't called me."],answer:1,explanation:"Sau trợ động từ qu\xe1 khứ phủ định 'didn't', động từ ch\xednh giữ nguy\xean thể 'call'."},{prompt:"Complete: “___ you finish the report last night?”",options:["Did","Do","Have"],answer:0,explanation:"C\xf3 'last night' (tối qua), c\xe2u hỏi qu\xe1 khứ đơn bắt đầu bằng 'Did you finish...'."}]},{id:"future-forms",level:"B1",title:"C\xe1c dạng tương lai: Will vs. Hiện tại tiếp diễn",structure:"Will + V (quyết định ngay l\xfac n\xf3i / phỏng đo\xe1n); To be + V-ing (lịch tr\xecnh đ\xe3 ấn định)",overview:"Ph\xe2n biệt c\xe1ch diễn đạt tương lai: 'Will' d\xf9ng khi đưa ra quyết định tức th\xec khi đang n\xf3i, hoặc dự đo\xe1n mang t\xednh chủ quan c\xe1 nh\xe2n. 'Hiện tại tiếp diễn' d\xf9ng cho kế hoạch chắc chắn đ\xe3 được sắp xếp, hẹn trước với người kh\xe1c (v\xed dụ: đ\xe3 hẹn b\xe1c sĩ, đ\xe3 mua v\xe9).",examples:["I am meeting the supplier at 10 a.m. (T\xf4i đ\xe3 hẹn gặp nh\xe0 cung ứng v\xe0o l\xfac 10 giờ s\xe1ng.)","I think the project will succeed. (T\xf4i nghĩ dự \xe1n n\xe0y sẽ th\xe0nh c\xf4ng.)"],questions:[{prompt:"The appointment is confirmed: “I ___ the doctor at 3 p.m. tomorrow.”",options:["see","am seeing","will seeing"],answer:1,explanation:"Cuộc hẹn đ\xe3 được x\xe1c nhận (confirmed), d\xf9ng th\xec hiện tại tiếp diễn chỉ kế hoạch: 'am seeing'."},{prompt:"The phone is ringing. “I ___ it.”",options:["am answering","will answer","answering"],answer:1,explanation:"Quyết định ngay khi chu\xf4ng điện thoại reo: 'I will answer it' (Để t\xf4i nghe m\xe1y cho)."},{prompt:"Complete: “I think prices ___ next year.”",options:["will rise","are rise","rising"],answer:0,explanation:"Sau cụm từ phỏng đo\xe1n 'I think', d\xf9ng 'will + V' ('will rise')."}]},{id:"modals-obligation",level:"B1",title:"Động từ khuyết thiếu: Lời khuy\xean & Bắt buộc (Modals)",structure:"Should + V (khuy\xean n\xean); Must / Have to + V (bắt buộc)",overview:"'Should' d\xf9ng để đưa ra lời khuy\xean hữu \xedch ('bạn n\xean l\xe0m g\xec'). 'Must' diễn tả sự bắt buộc hoặc quy định nghi\xeam ngặt; 'Have to' diễn tả sự cần thiết do y\xeau cầu kh\xe1ch quan b\xean ngo\xe0i. Sau động từ khuyết thiếu lu\xf4n l\xe0 động từ nguy\xean thể kh\xf4ng c\xf3 'to'.",examples:["You should review the instructions. (Bạn n\xean xem lại hướng dẫn.)","Employees must wear safety glasses. (Nh\xe2n vi\xean bắt buộc phải đeo k\xednh bảo hộ.)"],questions:[{prompt:"Choose the best advice: “The report has several errors.”",options:["You should check the figures again.","You should to check the figures again.","You checking the figures again."],answer:0,explanation:"Cấu tr\xfac lời khuy\xean chuẩn: 'should + V nguy\xean thể' (kh\xf4ng c\xf3 to)."},{prompt:"Complete: “Employees ___ wear protective equipment in this area.”",options:["must","must to","must wearing"],answer:0,explanation:"'Must' đi trực tiếp với động từ nguy\xean thể 'wear' chỉ quy định bắt buộc."},{prompt:"Complete: “I ___ submit the form today because the deadline is tomorrow.”",options:["have to","have","should to"],answer:0,explanation:"'Have to + V' diễn tả y\xeau cầu bắt buộc v\xec c\xf3 hạn ch\xf3t (deadline) b\xean ngo\xe0i."}]},{id:"first-conditional",level:"B1",title:"C\xe2u điều kiện loại 1 (First Conditional)",structure:"Mệnh đề If: Hiện tại đơn (Present Simple) | Mệnh đề ch\xednh: Will + V",overview:"D\xf9ng để diễn tả một điều kiện c\xf3 thật, c\xf3 thể xảy ra ở hiện tại hoặc tương lai v\xe0 kết quả của n\xf3. Lưu \xfd rất quan trọng: Kh\xf4ng bao giờ d\xf9ng 'will' ngay trong mệnh đề c\xf3 'If' (kh\xf4ng n\xf3i 'If it will rain').",examples:["If the temperature rises, the alarm will sound. (Nếu nhiệt độ tăng l\xean, chu\xf4ng b\xe1o động sẽ reo.)","We will call you if the delivery arrives. (Ch\xfang t\xf4i sẽ gọi cho bạn nếu h\xe0ng tới.)"],questions:[{prompt:"Complete: “If the customer ___ now, I will answer the call.”",options:["calls","will call","called"],answer:0,explanation:"Trong mệnh đề If của c\xe2u điều kiện loại 1, lu\xf4n d\xf9ng th\xec hiện tại đơn ('calls')."},{prompt:"Choose the correct sentence.",options:["If we leave early, we will arrive on time.","If we will leave early, we arrive on time.","If we left early, we will arrive on time."],answer:0,explanation:"Cấu tr\xfac chuẩn: 'If + S + V(hiện tại), S + will + V(nguy\xean thể)'."},{prompt:"Complete: “The meeting will start on time if everyone ___ ready.”",options:["is","will be","was"],answer:0,explanation:"'Everyone' l\xe0 đại từ số \xedt, mệnh đề If d\xf9ng hiện tại đơn với to be l\xe0 'is'."}]},{id:"present-perfect",level:"B1",title:"Th\xec Hiện tại ho\xe0n th\xe0nh (Present Perfect)",structure:"S + have / has + V3 / V-ed",overview:"D\xf9ng để diễn tả trải nghiệm đ\xe3 từng l\xe0m t\xednh đến nay (kh\xf4ng n\xeau r\xf5 thời gian cụ thể), hoặc một h\xe0nh động bắt đầu trong qu\xe1 khứ v\xe0 vẫn đang tiếp diễn đến hiện tại (thường đi với since / for).",examples:["I have used this system before. (T\xf4i đ\xe3 từng d\xf9ng hệ thống n\xe0y trước đ\xe2y.)","She has worked here since 2022. (C\xf4 ấy đ\xe3 l\xe0m việc ở đ\xe2y từ năm 2022 đến nay.)"],questions:[{prompt:"Complete: “I ___ this model before.”",options:["have used","used","am using"],answer:0,explanation:"C\xf3 từ 'before' diễn tả trải nghiệm c\xe1 nh\xe2n, d\xf9ng th\xec hiện tại ho\xe0n th\xe0nh: 'have used'."},{prompt:"Choose the correct sentence.",options:["She has worked here since 2022.","She have worked here since 2022.","She worked here since 2022."],answer:0,explanation:"Chủ ngữ 'She' đi với trợ động từ 'has' v\xe0 'since + mốc thời gian qu\xe1 khứ'."},{prompt:"Complete: “They ___ the inspection yet.”",options:["haven't completed","didn't completed","aren't complete"],answer:0,explanation:"Trong c\xe2u phủ định c\xf3 từ 'yet' (chưa), d\xf9ng hiện tại ho\xe0n th\xe0nh: 'haven't completed'."}]},{id:"passive-voice",level:"B2",title:"C\xe2u Bị động (Passive Voice)",structure:"S + Be (chia theo th\xec) + V3 / V-ed (Qu\xe1 khứ ph\xe2n từ)",overview:"D\xf9ng c\xe2u bị động khi muốn nhấn mạnh v\xe0o đối tượng chịu t\xe1c động hoặc kết quả của h\xe0nh động, thay v\xec người thực hiện h\xe0nh động. To be được chia theo th\xec của c\xe2u, sau đ\xf3 lu\xf4n l\xe0 động từ dạng V3/V-ed.",examples:["The forms are checked every morning. (C\xe1c biểu mẫu được kiểm tra v\xe0o mỗi buổi s\xe1ng.)","The appointment was confirmed yesterday. (Lịch hẹn đ\xe3 được x\xe1c nhận v\xe0o h\xf4m qua.)"],questions:[{prompt:"Choose the correct sentence.",options:["The forms checked every morning.","The forms are checked every morning.","The forms are checking every morning."],answer:1,explanation:"C\xe2u bị động ở hiện tại đơn số nhiều: 'are + V3' (are checked)."},{prompt:"Complete: “The appointment ___ by the clinic yesterday.”",options:["was confirmed","confirmed","is confirming"],answer:0,explanation:"Lịch hẹn (số \xedt) được x\xe1c nhận v\xe0o h\xf4m qua (qu\xe1 khứ đơn bị động): 'was confirmed'."},{prompt:"Complete: “The results will ___ tomorrow.”",options:["announce","be announced","be announcing"],answer:1,explanation:"Bị động ở tương lai đơn c\xf3 cấu tr\xfac: 'will be + V3' (will be announced)."}]},{id:"reported-speech",level:"B2",title:"C\xe2u Gi\xe1n tiếp / Tường thuật (Reported Speech)",structure:"S + said / told that + mệnh đề l\xf9i th\xec",overview:"D\xf9ng để kể lại lời của người kh\xe1c. Khi động từ tường thuật ở qu\xe1 khứ (said, told), c\xe1c th\xec trong lời n\xf3i trực tiếp thường l\xf9i 1 th\xec về qu\xe1 khứ (hiện tại đơn -> qu\xe1 khứ đơn; will -> would), đồng thời đổi đại từ nh\xe2n xưng v\xe0 trạng từ chỉ thời gian cho ph\xf9 hợp.",examples:["Lan said that she was busy. (Lan n\xf3i rằng c\xf4 ấy đang bận.)","They said they had finished the task. (Họ n\xf3i rằng họ đ\xe3 ho\xe0n th\xe0nh nhiệm vụ.)"],questions:[{prompt:"Report: “I am busy,” said Lan.",options:["Lan said that she was busy.","Lan said that I am busy.","Lan said that she is busy yesterday."],answer:0,explanation:"Lời n\xf3i trực tiếp d\xf9ng 'am' th\xec khi tường thuật với 'said' phải l\xf9i th\xec th\xe0nh 'was' v\xe0 đổi 'I' th\xe0nh 'she'."},{prompt:"Report: “We finished the task,” they said.",options:["They said they have finished the task.","They said they had finished the task.","They said they finish the task."],answer:1,explanation:"Qu\xe1 khứ đơn 'finished' khi tường thuật thường l\xf9i về qu\xe1 khứ ho\xe0n th\xe0nh 'had finished'."},{prompt:"Choose the correct reported statement: “I will call you,” Minh said.",options:["Minh said that he would call me.","Minh said that he will called me.","Minh said that I would call him."],answer:0,explanation:"'Will' khi tường thuật với động từ qu\xe1 khứ 'said' sẽ đổi th\xe0nh 'would'."}]},{id:"conditionals",level:"B2",title:"C\xe2u Điều kiện loại 2 (Second Conditional)",structure:"Mệnh đề If: Qu\xe1 khứ đơn (Past Simple) | Mệnh đề ch\xednh: Would + V",overview:"D\xf9ng để giả định một t\xecnh huống kh\xf4ng c\xf3 thật, tr\xe1i với thực tế ở hiện tại hoặc kh\xf3 xảy ra ở tương lai. Động từ to be trong mệnh đề If thường d\xf9ng 'were' cho tất cả c\xe1c ng\xf4i trong văn phong chuẩn.",examples:["If I had more time, I would take another course. (Nếu t\xf4i c\xf3 nhiều thời gian hơn, t\xf4i sẽ tham gia th\xeam một kh\xf3a học.)","If the unit were quieter, it would suit this office. (Nếu cỗ m\xe1y \xeam hơn, n\xf3 sẽ rất ph\xf9 hợp với văn ph\xf2ng n\xe0y.)"],questions:[{prompt:"Complete: “If the unit ___ quieter, it would suit this office.”",options:["is","were","will be"],answer:1,explanation:"C\xe2u điều kiện loại 2 giả định tr\xe1i thực tế, d\xf9ng 'were' trong mệnh đề If."},{prompt:"Choose the correct sentence.",options:["If I knew the answer, I would tell you.","If I would know the answer, I told you.","If I know the answer, I would told you."],answer:0,explanation:"Mệnh đề If d\xf9ng qu\xe1 khứ đơn (knew), mệnh đề ch\xednh d\xf9ng 'would + V' (would tell)."},{prompt:"Complete: “What ___ you do if a customer reported a safety issue?”",options:["will","would","did"],answer:1,explanation:"C\xe2u hỏi điều kiện loại 2 về t\xecnh huống giả định: 'What would you do if...?'."}]},{id:"relative-clauses",level:"B2",title:"Mệnh đề Quan hệ x\xe1c định (Defining Relative Clauses)",structure:"Danh từ + who (người) / which (vật) / that (cả hai) + mệnh đề phụ",overview:"D\xf9ng để bổ nghĩa v\xe0 x\xe1c định r\xf5 đối tượng được nhắc đến l\xe0 ai hoặc c\xe1i n\xe0o. D\xf9ng 'who' cho người, 'which' cho đồ vật/con vật, v\xe0 'that' c\xf3 thể thay thế cho cả who/which trong văn phong th\xe2n mật. Kh\xf4ng d\xf9ng dấu phẩy ngăn c\xe1ch mệnh đề quan hệ x\xe1c định.",examples:["The nurse who spoke to me was helpful. (Người y t\xe1 đ\xe3 n\xf3i chuyện với t\xf4i rất nhiệt t\xecnh.)","A warranty is a document that explains the coverage. (Bảo h\xe0nh l\xe0 văn bản giải th\xedch phạm vi bảo đảm.)"],questions:[{prompt:"Choose the correct sentence.",options:["The nurse which spoke to me was helpful.","The nurse who spoke to me was helpful.","The nurse where spoke to me was helpful."],answer:1,explanation:"'Nurse' (y t\xe1) l\xe0 người n\xean d\xf9ng đại từ quan hệ 'who'."},{prompt:"Complete: “The valve ___ controls the flow is damaged.”",options:["who","which","where"],answer:1,explanation:"'The valve' (van điều tiết) l\xe0 đồ vật n\xean d\xf9ng đại từ quan hệ 'which'."},{prompt:"Choose the sentence with the correct defining clause.",options:["A warranty is a document that explains the coverage.","A warranty is a document who explains the coverage.","A warranty is a document where explains the coverage."],answer:0,explanation:"'That' được d\xf9ng thay cho 'which' để bổ nghĩa cho danh từ chỉ vật 'document'."}]}],storagePrefix:"lingua-",defaults:{level:"A2",profile:"business"},mascot:{kind:"nova",badge:"\uD83C\uDF31 Linh vật"}}}}]);